package com.johnny.hotel.financeexpense;
import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.guest.GuestAccess;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.repair.RepairOrderMapper;import com.johnny.hotel.workorder.RoomWorkOrderMapper;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor public class HotelExpenseService{private static final Set<String>FINANCE=Set.of("FINANCE","OWNER","SUPER_ADMIN"),APPROVERS=Set.of("FINANCE","OWNER","SUPER_ADMIN"),METHODS=Set.of("CASH","CARD","BANK_TRANSFER","OFFLINE_CARD","OTHER");private final HotelExpenseMapper db;private final GuestAccess access;private final BusinessDateService dates;private final PaymentCoreMapper transactions;private final SysAuditLogMapper audits;private final RoomWorkOrderMapper workOrders;private final RepairOrderMapper repairs;private final PaginationSupport pages;private final Clock clock;
 @Transactional public HotelExpense create(ExpenseCommands.Create c,Long actor){var roles=roles(actor);boolean manager=roles.contains("MANAGER");if(!manager&&roles.stream().noneMatch(FINANCE::contains))throw denied();if(manager&&!Set.of(ExpenseCategory.MAINTENANCE,ExpenseCategory.SUPPLIES,ExpenseCategory.VENDOR,ExpenseCategory.OTHER).contains(c.category()))throw denied();var old=db.byRequest(actor,c.requestKey());if(old!=null){same(old,c);return old;}related(c.relatedType(),c.relatedId());if(c.category()==ExpenseCategory.PAYROLL&&c.employeeUserId()==null)throw bad("Payroll expense requires employee reference");var e=HotelExpense.builder().amount(c.amount().setScale(2)).currency(c.currency().toUpperCase(Locale.ROOT)).category(c.category().name()).description(c.description().trim()).referenceNo(trim(c.referenceNo())).expenseDate(c.expenseDate()).serviceDate(c.serviceDate()).status(0).createdBy(actor).relatedType(norm(c.relatedType())).relatedId(c.relatedId()).employeeUserId(c.employeeUserId()).requestKey(c.requestKey()).build();one(db.insert(e));action(e.getId(),"CREATED",c.requestKey(),actor,null);audit(actor,e.getId(),"CREATE_HOTEL_EXPENSE");return db.find(e.getId());}
 @Transactional public HotelExpense submit(Long id,ExpenseCommands.Action c,Long actor){var e=lock(id);canOperate(e,actor);if(e.getStatus()==1)return e;require(e.getStatus()==0,"Only draft expense can be submitted");one(db.submit(id));action(id,"SUBMITTED",c.requestKey(),actor,c.reason());audit(actor,id,"SUBMIT_HOTEL_EXPENSE");return db.find(id);}
 @Transactional public HotelExpense approve(Long id,ExpenseCommands.Action c,Long actor){approveRole(actor);var e=lock(id);if(e.getStatus()>=2&&e.getStatus()!=4&&e.getStatus()!=5)return e;require(e.getStatus()==1,"Only pending expense can be approved");require(!actor.equals(e.getCreatedBy()),"Expense creator cannot approve own expense");one(db.approve(id,actor,now()));action(id,"APPROVED",c.requestKey(),actor,c.reason());audit(actor,id,"APPROVE_HOTEL_EXPENSE");return db.find(id);}
 @Transactional public HotelExpense reject(Long id,ExpenseCommands.Action c,Long actor){approveRole(actor);var e=lock(id);if(e.getStatus()==4)return e;require(e.getStatus()==1,"Only pending expense can be rejected");require(!actor.equals(e.getCreatedBy()),"Expense creator cannot reject own expense");require(c.reason()!=null&&!c.reason().isBlank(),"Rejection reason is required");one(db.reject(id,actor,now(),c.reason().trim()));action(id,"REJECTED",c.requestKey(),actor,c.reason());audit(actor,id,"REJECT_HOTEL_EXPENSE");return db.find(id);}
 @Transactional public HotelExpense cancel(Long id,ExpenseCommands.Action c,Long actor){var e=lock(id);canOperate(e,actor);if(e.getStatus()==5)return e;require(e.getStatus()==0||e.getStatus()==1,"Expense can no longer be cancelled");one(db.cancel(id));action(id,"CANCELLED",c.requestKey(),actor,c.reason());audit(actor,id,"CANCEL_HOTEL_EXPENSE");return db.find(id);}
 @Transactional public HotelExpense pay(Long id,ExpenseCommands.Pay c,Long actor){finance(actor);var e=lock(id);if(e.getStatus()==3)return e;require(e.getStatus()==2,"Only approved expense can be paid");String method=norm(c.paymentMethod());require(METHODS.contains(method),"Unsupported expense payment method");LocalDate posting=dates.postingDate();LocalDateTime at=now();one(db.paid(id,posting,actor,at,method,trim(c.externalReference())));var tx=HotelTransactionRecord.builder().direction("EXTERNAL_OUT").amount(e.getAmount()).currency(e.getCurrency()).sourceType("EXPENSE").sourceId(id).businessReferenceType("EXPENSE").businessReferenceId(id).paymentMethod(method).channel("FINANCE_OPERATIONS").provider(null).providerTransactionId(trim(c.externalReference())).initiatorType("HOTEL").operatorUserId(actor).description("Hotel expense "+id).occurredAt(at).businessDate(posting).build();one(transactions.insertTransaction(tx));action(id,"PAID",c.requestKey(),actor,null);audit(actor,id,"PAY_HOTEL_EXPENSE");return db.find(id);}
 @Transactional public ExpenseReversal requestReversal(Long expenseId,ExpenseReversalCommands.Request c,Long actor){finance(actor);var old=db.reversalByKey(c.requestKey());if(old!=null){require(old.getExpenseId().equals(expenseId)&&old.getAmount().compareTo(c.amount())==0,"Reversal request key conflicts with another request");return old;}var e=lock(expenseId);require(e.getStatus()==3,"Only paid expense can be reversed");BigDecimal reserved=db.reservedReversal(expenseId);require(reserved.add(c.amount()).compareTo(e.getAmount())<=0,"Expense reversal exceeds remaining paid amount");var r=ExpenseReversal.builder().expenseId(expenseId).amount(c.amount().setScale(2)).reason(c.reason().trim()).requestKey(c.requestKey()).initiatedBy(actor).status(0).build();one(db.insertReversal(r));action(expenseId,"REVERSAL_REQUESTED",c.requestKey(),actor,c.reason());audit(actor,expenseId,"REQUEST_EXPENSE_REVERSAL");return db.reversal(r.getId());}
 @Transactional public ExpenseReversal approveReversal(Long reversalId,ExpenseReversalCommands.Approve c,Long actor){finance(actor);var snapshot=db.reversal(reversalId);if(snapshot==null)throw bad("Expense reversal does not exist");var e=lock(snapshot.getExpenseId());var r=db.lockReversal(reversalId);if(r.getStatus()==1)return r;require(r.getStatus()==0,"Expense reversal is already resolved");require(!actor.equals(r.getInitiatedBy()),"Reversal initiator cannot approve own request");require(c.fundsReturnedConfirmed(),"Actual returned funds must be confirmed");require(db.completedReversal(e.getId()).add(r.getAmount()).compareTo(e.getAmount())<=0,"Expense reversal exceeds paid amount");LocalDate posting=dates.postingDate();LocalDateTime at=now();one(db.approveReversal(reversalId,actor,posting,at,trim(c.externalReference())));one(transactions.insertTransaction(HotelTransactionRecord.builder().direction("EXTERNAL_IN").amount(r.getAmount()).currency(e.getCurrency()).sourceType("EXPENSE_REVERSAL").sourceId(reversalId).businessReferenceType("EXPENSE").businessReferenceId(e.getId()).paymentMethod(e.getPaymentMethod()).channel("FINANCE_OPERATIONS").provider(null).providerTransactionId(trim(c.externalReference())).initiatorType("HOTEL").operatorUserId(actor).description("Expense reversal "+reversalId).occurredAt(at).businessDate(posting).build()));action(e.getId(),"REVERSAL_COMPLETED",c.requestKey(),actor,r.getReason());audit(actor,e.getId(),"APPROVE_EXPENSE_REVERSAL");return db.reversal(reversalId);}
 @Transactional public ExpenseReversal rejectReversal(Long reversalId,ExpenseReversalCommands.Reject c,Long actor){finance(actor);var r=db.lockReversal(reversalId);if(r==null)throw bad("Expense reversal does not exist");if(r.getStatus()==2)return r;require(r.getStatus()==0,"Expense reversal is already resolved");require(!actor.equals(r.getInitiatedBy()),"Reversal initiator cannot reject own request");one(db.rejectReversal(reversalId,actor,c.reason().trim()));action(r.getExpenseId(),"REVERSAL_REJECTED",c.requestKey(),actor,c.reason());audit(actor,r.getExpenseId(),"REJECT_EXPENSE_REVERSAL");return db.reversal(reversalId);}
 @Transactional(readOnly=true)public ExpenseDetail detail(Long id,Long actor){var roles=roles(actor);var e=db.find(id);if(e==null)throw bad("Expense does not exist");if(roles.contains("MANAGER")&&!actor.equals(e.getCreatedBy()))throw denied();if(!roles.contains("MANAGER")&&roles.stream().noneMatch(FINANCE::contains))throw denied();BigDecimal reversed=db.completedReversal(id),original=e.getStatus()==3?e.getAmount():BigDecimal.ZERO,net=original.subtract(reversed);return ExpenseDetail.builder().expense(e).originalPaidAmount(original).reversedAmount(reversed).netCashExpense(net).fullyReversed(original.signum()>0&&net.signum()==0).reversals(db.reversals(id)).build();}
 @Transactional(readOnly=true)public PageResult<HotelExpense> query(LocalDate from,LocalDate to,Integer status,String category,Long createdBy,Integer page,Integer size,Long actor){var roles=roles(actor);if(roles.contains("MANAGER"))createdBy=actor;else if(roles.stream().noneMatch(FINANCE::contains))throw denied();if(from!=null&&to!=null&&from.isAfter(to))throw bad("Date range is invalid");var w=pages.window(page,size,true);String cat=norm(category);return pages.result(w,db.page(from,to,status,cat,createdBy,w.offset(),pages.limit(w)),db.count(from,to,status,cat,createdBy));}
 private void related(String type,Long id){String t=norm(type);if(t==null&&id==null)return;require(t!=null&&id!=null,"Related type and id must be supplied together");if("WORK_ORDER".equals(t))require(workOrders.find(id)!=null,"Work order does not exist");else if("REPAIR_ORDER".equals(t))require(repairs.find(id)!=null,"Repair order does not exist");else throw bad("Unsupported expense relation");}
 private void same(HotelExpense e,ExpenseCommands.Create c){require(e.getAmount().compareTo(c.amount())==0&&e.getCategory().equals(c.category().name())&&e.getCurrency().equalsIgnoreCase(c.currency()),"Expense request key conflicts with a different request");}
 private Set<String>roles(Long a){return access.activeRoles(a);}private void finance(Long a){if(roles(a).stream().noneMatch(FINANCE::contains))throw denied();}private void approveRole(Long a){if(roles(a).stream().noneMatch(APPROVERS::contains))throw denied();}private void read(Long a){finance(a);}private void canOperate(HotelExpense e,Long a){var r=roles(a);if(a.equals(e.getCreatedBy())||r.stream().anyMatch(FINANCE::contains))return;throw denied();}private HotelExpense lock(Long id){var e=db.lock(id);if(e==null)throw bad("Expense does not exist");return e;}private void action(Long id,String type,String key,Long actor,String reason){one(db.action(id,type,key,actor,trim(reason)));}private void audit(Long actor,Long id,String action){one(audits.insert(SysAuditLog.builder().operatorId(actor).targetUserId(actor).action(action).detail("Expense id: "+id).build()));}private LocalDateTime now(){return LocalDateTime.now(clock);}private String norm(String s){return s==null||s.isBlank()?null:s.trim().toUpperCase(Locale.ROOT);}private String trim(String s){return s==null||s.isBlank()?null:s.trim();}private void one(int n){if(n!=1)throw bad("Expense state changed concurrently");}private void require(boolean ok,String m){if(!ok)throw bad(m);}private BusinessException bad(String m){return new BusinessException(m);}private AccessDeniedException denied(){return new AccessDeniedException("Expense access denied");}
}
